import{_ as i}from"./chunks/Audio.COine8Wh.js";import{c as o,o as a,j as t,G as r,ae as n,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"MODIFYING THE SCOPE OF TARIFFS ON THE GOVERNMENT OF BRAZIL","description":"","frontmatter":{"legisId":"2025-11-20-modifying-the-scope-of-tariffs-on-the-government-of-brazil","title":"MODIFYING THE SCOPE OF TARIFFS ON THE GOVERNMENT OF BRAZIL","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/11/modifying-the-scope-of-tariffs-on-the-government-of-brazil/","publishDate":"2025-11-20T16:37:03-05:00"},"headers":[],"relativePath":"executive-orders/2025-11-20-modifying-the-scope-of-tariffs-on-the-government-of-brazil.md","filePath":"executive-orders/2025-11-20-modifying-the-scope-of-tariffs-on-the-government-of-brazil.md"}'),l={name:"executive-orders/2025-11-20-modifying-the-scope-of-tariffs-on-the-government-of-brazil.md"},u=Object.assign(l,{setup(d){return(f,e)=>(a(),o("div",null,[e[0]||(e[0]=t("h1",{id:"modifying-the-scope-of-tariffs-on-the-government-of-brazil",tabindex:"-1"},[s("MODIFYING THE SCOPE OF TARIFFS ON THE GOVERNMENT OF BRAZIL "),t("a",{class:"header-anchor",href:"#modifying-the-scope-of-tariffs-on-the-government-of-brazil","aria-label":'Permalink to "MODIFYING THE SCOPE OF TARIFFS ON THE GOVERNMENT OF BRAZIL"'},"​")],-1)),r(i),e[1]||(e[1]=n('<p>Published on Thursday, November 20, 2025</p><ul><li>The President has the authority through the Constitution and U.S. laws, including the IEEPA and National Emergencies Act.</li><li>Executive Order 14323 previously declared a national emergency regarding actions of the Brazilian government, identified as a threat to U.S. national security, foreign policy, and economy.</li><li>A 40% additional duty rate was imposed on certain Brazilian articles to address this threat.</li><li>Ongoing negotiations with Brazilian President Luiz Inácio Lula da Silva aim to resolve the identified concerns.</li><li>Recommendations suggest that certain agricultural imports from Brazil may no longer require the additional duty due to progress in negotiations.</li><li>Modifications to the additional duty rate will exclude specific agricultural products; an updated Annex I will be effective from November 13, 2025, for applicable goods.</li><li>The Harmonized Tariff Schedule of the U.S. will be updated according to Annex II, effective from the same date.</li><li>Refunds for collected duties will follow U.S. Customs and Border Protection&#39;s procedures.</li><li>The Secretary of State will monitor the emergency situation and consult with senior officials, reporting any actions that may be needed.</li><li>The President has authorized the Secretary of State and other relevant departments to implement the provisions of the order, consistent with existing laws.</li><li>The order includes clauses on the inviolability of its provisions, the authority of executive departments, and limitations on rights enforceable against the U.S. and its entities.</li><li>Costs of publication are to be covered by the Department of State.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/11/modifying-the-scope-of-tariffs-on-the-government-of-brazil/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/11/modifying-the-scope-of-tariffs-on-the-government-of-brazil/</a></p>',3))]))}});export{m as __pageData,u as default};
